#ifndef NPE_TYPES_H_
#define NPE_TYPES_H_

// Weight words are P * P * PO * PI * 8 bits wide.
#ifndef AP_INT_MAX_W
#define AP_INT_MAX_W 8192
#endif
#include <ap_int.h>
#include <hls_stream.h>
#include <stdint.h>

#include "npe_config.h" // generated per program by npe/compiler/pack.py
#include "npe_isa.h"    // generated by npe/compiler/isa.py

// Parallelism knobs (set per build in npe_config.h by the packer):
//   NPE_PO  output words per cycle in the dense conv unit
//   NPE_PI  input words per cycle in the dense conv unit
//           -> P * P * PO * PI multipliers
//   NPE_PC  channel words per cycle in the depthwise and max-pool units
//           -> P * PC multipliers (depthwise)
//   NPE_RQ  depthwise output words requantized per cycle (<= PC; the
//           requant multipliers are shared over a group's taps)
//   NPE_RQC dense conv output words requantized per cycle (<= PO)
//   NPE_NB  banks per feature buffer (power of two, >= 2 PO, PI, PC): any
//           NB consecutive words sit in different banks, so a unit can read
//           or write that many in one cycle.

// Memory layouts are defined in npe/compiler/pack.py.
typedef ap_uint<8 * NPE_P> npe_word_t;          // P channels of one pixel
// PO x PI blocks of P x P int8 weights
typedef ap_uint<8 * NPE_P * NPE_P * NPE_PO * NPE_PI> npe_wword_t;
// quant lanes of one output word: P x (bias, M, S), plus P x Mb with ADD
#define NPE_QL ((NPE_HAS_ADD ? 104 : 72) * NPE_P)
typedef ap_uint<NPE_QL * NPE_PO> npe_qword_t;   // PO output words
typedef ap_uint<8 * NPE_P * NPE_PC> npe_dwword_t; // one tap of PC words
typedef ap_uint<72 * NPE_P * NPE_PC> npe_qdword_t; // depthwise quant, PC words
typedef ap_int<32> npe_acc_t;                   // MAC accumulator
typedef ap_uint<32 * NPE_P> npe_vword_t;        // P int32 (buffer V)

typedef ap_uint<8 * NPE_IN_C> npe_pixel_t;      // one input image pixel

// IN, the input image: NPE_IN_PPB banks, pixel p in bank p % PPB, row p / PPB,
// so PPB consecutive pixels can be loaded (one AXI beat) and read (the
// image layer packs IN_PPW pixels of a kernel row into one word) per cycle.
#define NPE_IN_ROWS ((NPE_IN_PIXELS + NPE_IN_PPB - 1) / NPE_IN_PPB + 1)

// Feature buffers S0, A, B, C: NB banks, word w in bank w % NB, row w / NB.
// IN (the input image) is a read-only memory of pixels (above). V holds int32
// vectors (GAP sums, fc input). OUT is the output stream of int32 results.
#define NPE_ROWS(words) ((words) / NPE_NB)
#define NPE_BUF_PARAMS                                                         \
  const npe_pixel_t IN[NPE_IN_PPB][NPE_IN_ROWS],                                         \
      npe_word_t S0[NPE_NB][NPE_ROWS(NPE_BUF_S0_WORDS)],                       \
      npe_word_t A[NPE_NB][NPE_ROWS(NPE_BUF_A_WORDS)],                         \
      npe_word_t B[NPE_NB][NPE_ROWS(NPE_BUF_B_WORDS)],                         \
      npe_word_t C[NPE_NB][NPE_ROWS(NPE_BUF_C_WORDS)],                         \
      npe_vword_t V[NPE_V_WORDS], hls::stream<npe_acc_t> &OUT
#define NPE_BUF_ARGS IN, S0, A, B, C, V, OUT
// Weight streaming (see npe_wstream.h). W holds the resident words at
// 0 .. NPE_W_RING_BASE - 1, then a ring of NPE_W_RING words (a power of two,
// 0 = no streamed layers) that layers with w_stream read from. Their words
// arrive on WS, NPE_WS_BITS per beat, in the order the engine uses them.
#ifndef NPE_W_RING
#define NPE_W_RING 0
#endif
#ifndef NPE_W_RING_BASE
#define NPE_W_RING_BASE 0
#endif
#ifndef NPE_WS_BITS
#define NPE_WS_BITS 128
#endif
typedef ap_uint<NPE_WS_BITS> npe_ws_t; // one beat of the weight stream
// Ring state, kept across the instructions of one run.
struct npe_wring_t {
  int wr;           // stream words written into the ring so far
  int pos;          // stream word where the next streamed layer starts
  int nbeat;        // beats of the word being assembled
  npe_wword_t part; // the word being assembled
};

#define NPE_MEM_PARAMS                                                         \
  npe_wword_t W[NPE_W_WORDS], const npe_dwword_t WD[NPE_WD_WORDS],            \
      const npe_qword_t Q[NPE_Q_WORDS], const npe_qdword_t QD[NPE_QD_WORDS],  \
      hls::stream<npe_ws_t> &WS, npe_wring_t &WR
#define NPE_MEM_ARGS W, WD, Q, QD, WS, WR

#endif // NPE_TYPES_H_
